import React, { useState, useEffect } from "react";
import "../../styles/create-client-matter.css";
import Logo from "../../../../assets/logo-filled.png";
import { Button, Field, SearchBox, Checkbox, Spinner } from "@fluentui/react-components";
import { FolderOpen, RefreshCw } from "lucide-react";
import { useNavigate } from "react-router-dom";
import Loader from "../../components/loader";
import { getOneDriveFolders } from "../../oneDrive/foldersJirerachy";
import { saveEmailToOneDrive } from "../../oneDrive/uploadToOneDrive";
import { ToastContainer, toast } from "react-toastify";
import Header from "../../components/Header/Header";

const Home = () => {
  const navigate = useNavigate();
  const [clientLocation, setClientLocation] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isEmailChecked, setIsEmailChecked] = useState(true);
  const [isAttachmentsChecked, setIsAttachmentsChecked] = useState(false);
  const [folders, setFolders] = useState([]);
  const [filteredFolder, setFilteredFolder] = useState([]);
  const [isLoadingFolders, setIsLoadingFolders] = useState(false);

  // Fetch folders when component mounts

  useEffect(() => {
    const initialize = async () => {
      // Fetch folders - accountManager will handle token acquisition automatically
      fetchFolders();
    };

    initialize();
  }, []);

  const fetchFolders = async () => {
    setClientLocation("");
    setIsLoading(true);

    try {
      const cached = window.localStorage.getItem("oneDriveFolders");

      if (cached && cached !== "[]") {
        const allFolders = JSON.parse(cached);
        setFolders(allFolders);
      } else {
        await syncDriveFolders(); // call the shared sync logic
      }
    } catch (error) {
      console.error("Error fetching folders:", error);
    } finally {
      setIsLoading(false);
    }
  };

  // Shared logic for syncing OneDrive folders with loading and error handling
  const syncDriveFolders = async () => {
    setIsLoading(true); // Start loader
    try {
      const folders = await getOneDriveFolders();
      setFolders(folders);
      window.localStorage.setItem("oneDriveFolders", JSON.stringify(folders));
      toast.success("Drive synced successfully!");
    } catch (err) {
      console.error("Error syncing folders:", err);
      toast.error("Failed to sync folders.");
    } finally {
      setIsLoading(false); // Stop loader
    }
  };

  // Handle search input changes
  const handleSearchChange = (e) => {
    const value = e?.target?.value?.trim().toLowerCase() || "";
    setClientLocation(value);
    setFilteredFolder(value === "" ? [] : folders.filter((folder) => folder.path.toLowerCase().includes(value)));
  };

  // Function to handle adding to client matter
  const handleAddToClientMatter = async () => {
    try {
      // 🛑 Validate Selection
      if (selectedIndex === null) {
        toast.error("Please select a client matter.");
        return;
      }

      if (!isEmailChecked && !isAttachmentsChecked) {
        toast.error("Please select at least one option to upload.");
        return;
      }

      const selectedFolder = filteredFolder[selectedIndex];

      if (!selectedFolder || !selectedFolder.id) {
        toast.error("Invalid selection. Please try again.");
        return;
      }

      // 🚀 Start loading
      setIsLoading(true);

      // 🛑 Check Attachments if Required
      const hasAttachments = Office.context.mailbox.item.attachments.length > 0;
      if (isAttachmentsChecked && !hasAttachments) {
        toast.error("No attachments to be saved from this email!");
        setIsLoading(false); // Stop loading if no attachments
        return;
      }

      // ✅ Proceed with saving
      await saveEmailToOneDrive(selectedFolder.path, isAttachmentsChecked, isEmailChecked);

      // 🎉 Success Notification
      toast.success("Saved to Matter successfully!");
    } catch (error) {
      console.error("❌ Error adding to Client Matter:", error);
      toast.error("Failed to save to Matter. Please try again.");
    } finally {
      // 🛑 Ensure loading state is turned off
      setIsLoading(false);
    }
  };

  return (
    <>
      {isLoading && <Loader />}
      <div className="home-container">
        <Header fetchFolders={fetchFolders} />
        <div className="background-overlay"></div>
        <div
          className="logo-style"
          style={{
            paddingTop: "60px",
          }}
        >
          <img src={Logo} alt="Logo" />
        </div>
        <div className="create-client-home">
          <ToastContainer position="bottom-center" autoClose={3000} hideProgressBar />

          {/* Search Box */}
          <div style={{ width: "285px" }}>
            <Field className="searchbox-field">
              <SearchBox
                className="searchbox"
                placeholder="Add to an existing client matter"
                value={clientLocation}
                onChange={handleSearchChange}
                onClear={() => {
                  setClientLocation("");
                  setFilteredFolder([]);
                }}
              />
            </Field>
          </div>

          {/* Checkboxes for Email and Attachments in a row */}
          <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center', gap: 16, margin: '12px 0' }}>
            <Checkbox
              size="large"
              label="Email"
              checked={isEmailChecked}
              onChange={() => setIsEmailChecked(!isEmailChecked)}
            />
            <Checkbox
              size="large"
              label="Attachments"
              checked={isAttachmentsChecked}
              onChange={() => setIsAttachmentsChecked(!isAttachmentsChecked)}
            />
          </div>

          {/* Folder List */}
          <div className="customer-matter-container">
            {isLoadingFolders ? (
              <p className="loading-text">
                <Spinner /> Loading Folders...
              </p>
            ) : filteredFolder.length > 0 ? (
              filteredFolder.map((matter, index) => (
                <p
                  key={matter.id} // Use unique folder ID as key
                  className={`customer-matter ${selectedIndex === index ? "selected" : ""}`}
                  onClick={() => setSelectedIndex(index)}
                >
                  <FolderOpen size={18} /> {matter.path}
                </p>
              ))
            ) : (
              <p className="no-folders-text">Search to fetch your folders.</p>
            )}
          </div>

          {/* Add to Client Matter Button */}
          <Button appearance="primary" className="add-client-btn" shape="circular" onClick={handleAddToClientMatter}>
            ADD TO CLIENT MATTER
          </Button>
        </div>
      </div>
    </>
  );
};

export default Home;
