import React from 'react';
import { Button, Menu, MenuTrigger, MenuPopover, MenuList, MenuItem } from '@fluentui/react-components';
import { Menu as MenuIcon, FolderPlus, RefreshCw, Settings } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const Header = ({ fetchFolders }) => {
  const navigate = useNavigate();

  const handleCreateMatter = () => {
    navigate('/CreateClientMatter');
  };

  const handleSyncDrive = () => {
    if (typeof fetchFolders === 'function') {
      fetchFolders();
    }
  };

  const handleSettings = () => {
    // Implement settings functionality
    console.log('Settings clicked');
  };

  return (
    <div style={{ 
      position: 'absolute', 
      top: 0, 
      left: 0, 
      padding: '10px',
      zIndex: 1000
    }}>
      <Menu>
        <MenuTrigger>
          <Button 
            appearance="transparent" 
            icon={<MenuIcon />}
            style={{ 
              minWidth: 'auto',
              padding: '4px',
              borderRadius: '50%'
            }}
          />
        </MenuTrigger>
        <MenuPopover>
          <MenuList>
            <MenuItem 
              icon={<FolderPlus size={18} />} 
              onClick={handleCreateMatter}
            >
              Create Matter
            </MenuItem>
            <MenuItem 
              icon={<RefreshCw size={18} />} 
              onClick={handleSyncDrive}
            >
              Sync Drive
            </MenuItem>
            <MenuItem 
              icon={<Settings size={18} />} 
              onClick={handleSettings}
            >
              Settings
            </MenuItem>
          </MenuList>
        </MenuPopover>
      </Menu>
    </div>
  );
};

export default Header; 