import { accountManager } from '../msal/authConfig';
import { config } from '../config';
import { getCurrentEmailAsEML, getAttachments } from "../Utilities/currentEmail";

// 📌 Save Email (and optionally attachments) to OneDrive
export async function saveEmailToOneDrive(folderPath, includeAttachments, includeEmail = true) {
  try {
    console.log("Starting email save process...");

    if (includeEmail) {
      // 1️⃣ Upload Email as .eml
      console.log("Fetching email...");
      const emailBlob = await getCurrentEmailAsEML();
      if (!emailBlob) {
        console.log("Failed to retrieve email.");
        return;
      }

      const emailSubject = Office.context.mailbox.item.subject || "Email";
      const fileName = `${emailSubject.replace(/[^a-zA-Z0-9]/g, "_")}.eml`;

      console.log(`Uploading email as ${fileName}...`);
      await uploadFileToOneDrive(emailBlob, fileName, folderPath);
    }

    if (includeAttachments) {
      // 2️⃣ Fetch & Upload Attachments
      console.log("Fetching attachments...");
      const attachments = await getAttachments();

      if (attachments.length === 0) {
        console.log("No attachments found.");
      } else {
        console.log(`Found ${attachments.length} attachments.`);
        for (const attachment of attachments) {
          console.log(`Uploading attachment: ${attachment.name}`);
          await uploadFileToOneDrive(attachment.blob, attachment.name, folderPath);
        }
      }
    }

    console.log("✅ File(s) saved successfully to OneDrive!");
  } catch (error) {
    console.error("❌ Error:", error);
    console.log("Failed to save email or attachments.");
  }
}

// 📌 Upload File to OneDrive
async function uploadFileToOneDrive(fileContent, fileName, folderPath) {
  try {
    const token = await accountManager.ssoGetToken(config.SCOPES);
    
    // Encode folder path for API
    const formattedPath = encodeURIComponent(folderPath);
    const uploadUrl = `https://graph.microsoft.com/v1.0/me/drive/root:/${formattedPath}/${fileName}:/content`;

    console.log(`Uploading file: ${fileName} to ${folderPath}`);

    const response = await fetch(uploadUrl, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/octet-stream",
      },
      body: fileContent,
    });

    if (response.status === 401) {
      // Token expired, clear it and retry once
      window.localStorage.removeItem('client_matter_token');
      const newToken = await accountManager.ssoGetToken(config.SCOPES);
      
      const retryResponse = await fetch(uploadUrl, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${newToken}`,
          "Content-Type": "application/octet-stream",
        },
        body: fileContent,
      });

      if (!retryResponse.ok) {
        throw new Error(`Upload failed: ${retryResponse.statusText}`);
      }
    } else if (!response.ok) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    console.log(`✅ Successfully uploaded ${fileName} to OneDrive!`);
  } catch (error) {
    console.error(`❌ Error uploading file: ${error.message}`);
    throw error;
  }
}
