import { accountManager } from '../msal/authConfig';
import { config } from '../config';

async function fetchFolders(parentId = "root", parentPath = "") {
  const endpoint =
    parentId === "root"
      ? "https://graph.microsoft.com/v1.0/me/drive/root/children?$top=200"
      : `https://graph.microsoft.com/v1.0/me/drive/items/${parentId}/children?$top=200`;

  let allFolders = [];

  try {
    let nextLink = endpoint;

    while (nextLink) {
      // Get fresh token for each request
      const token = await accountManager.ssoGetToken(config.SCOPES);
      
      const response = await fetch(nextLink, {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.status === 429) {
        const retryAfter = response.headers.get("Retry-After") || 5;
        console.warn(`Rate limit hit! Retrying after ${retryAfter} seconds...`);
        await new Promise((resolve) => setTimeout(resolve, retryAfter * 1000));
        return fetchFolders(parentId, parentPath);
      }

      if (response.status === 401) {
        // Token expired, clear it and retry once
        window.localStorage.removeItem('client_matter_token');
        const newToken = await accountManager.ssoGetToken(config.SCOPES);
        const retryResponse = await fetch(nextLink, {
          headers: { 
            'Authorization': `Bearer ${newToken}`,
            'Content-Type': 'application/json'
          }
        });
        
        if (!retryResponse.ok) {
          throw new Error(`Error fetching folders: ${retryResponse.statusText}`);
        }
        
        const data = await retryResponse.json();
        const folders = data.value
          .filter((item) => item.folder)
          .map((item) => ({
            id: item.id,
            name: item.name,
            path: parentPath ? `${parentPath}/${item.name}` : item.name,
          }));

        allFolders = allFolders.concat(folders);
        nextLink = data["@odata.nextLink"] || null;
        continue;
      }

      if (!response.ok) {
        throw new Error(`Error fetching folders: ${response.statusText}`);
      }

      const data = await response.json();
      const folders = data.value
        .filter((item) => item.folder)
        .map((item) => ({
          id: item.id,
          name: item.name,
          path: parentPath ? `${parentPath}/${item.name}` : item.name,
        }));

      allFolders = allFolders.concat(folders);
      nextLink = data["@odata.nextLink"] || null;
    }

    return allFolders;
  } catch (error) {
    console.error(`Error fetching folders for parent ${parentId}:`, error);
    return [];
  }
}

// ✅ Fetch **Root-Level Folders and Their Direct Children** into a Flat Array
export async function getOneDriveFolders() {
  try {
    let flatFolders = [];

    // Step 1: Fetch root-level folders
    const rootFolders = await fetchFolders("root");

    // Step 2: Fetch first-level children for each root folder
    for (let folder of rootFolders) {
      flatFolders.push(folder); // Add root folder to the list
      const subFolders = await fetchFolders(folder.id, folder.path);
      flatFolders = flatFolders.concat(subFolders); // Add subfolders
    }

    console.log(JSON.stringify(flatFolders, null, 2)); // Print flat folder structure
    return flatFolders;
  } catch (error) {
    console.error("Error fetching OneDrive folders:", error);
    return [];
  }
}

// 🌟 Fetch Sub-Folders On Demand (Lazy Load)
export async function getSubFolders(folderId) {
  try {
    const subFolders = await fetchFolders(folderId);
    console.log(`Sub-Folders of ${folderId}:`, subFolders);
    return subFolders;
  } catch (error) {
    console.error("Error fetching sub-folders:", error);
    return [];
  }
}
