import React, { useState, useEffect } from "react";
import Select from "react-select";
import "../../styles/create-client-matter.css";
import Logo from "../../../../assets/logo-filled.png";
import { Button, Input, Tooltip } from "@fluentui/react-components";
import { useNavigate } from "react-router-dom";
import { MoveLeft, RefreshCw, ChevronLeft } from "lucide-react";
import { useForm } from "react-hook-form";
import Loader from "../../components/loader";
import { createFolder } from "../../oneDrive/createFolder";
import { ToastContainer, toast } from "react-toastify";
import { getOneDriveFolders } from "../../oneDrive/foldersJirerachy";
import Header from "../../components/Header/Header";
import { CheckmarkCircle24Filled, FolderAdd24Filled } from '@fluentui/react-icons';

const CreateClientMatter = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [selectedOption, setSelectedOption] = useState(null);
  const [options, setOptions] = useState([]);
  const [parentFolders, setParentFolders] = useState([]);
  const [clientInput, setClientInput] = useState("");
  const [filteredOptions, setFilteredOptions] = useState([]);
  const [selectedPath, setSelectedPath] = useState("");
  const [addedClientId, setAddedClientId] = useState(null);
  const [pendingClientFolder, setPendingClientFolder] = useState(null);

  const navigate = useNavigate();
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({ mode: "onSubmit" });

  useEffect(() => {
    const stored = JSON.parse(window.window.localStorage.getItem("oneDriveFolders")) || [];
    setParentFolders(stored);


  }, []);

  // Update filteredOptions as user types in client name
  useEffect(() => {
    if (!clientInput) {
      setFilteredOptions([]);
      setOptions([]);
      return;
    }
    const matches = parentFolders.filter(folder =>
      folder.path.toLowerCase().includes(clientInput.toLowerCase())
    );
    setFilteredOptions(matches);

    if (matches.length > 0) {
      setOptions(matches.map(folder => ({ value: folder.path, label: folder.name })));
    } else {
      // Show all possible parent locations if no match
      setOptions(parentFolders.map(folder => ({ value: folder.path, label: folder.name })));
    }
  }, [clientInput, parentFolders]);

  const goToHome = () => {
    navigate("/");
  };

  // Handler for folder add icon button
  const handleAddFolder = () => {
    if (!selectedOption) {
      toast.error("Please select a location first");
      return;
    }
    const clientNameTrimmed = clientInput.trim();
    if (!clientNameTrimmed) {
      toast.error("Please enter a client name");
      return;
    }
    const newPath = `${selectedOption.value}/${clientNameTrimmed}`;
    setPendingClientFolder({ name: clientNameTrimmed, path: newPath });
    toast.success("Client folder ready to be created. Now enter the matter name and submit.");
  };

  const onSubmitHandler = async (data) => {
    setIsLoading(true);
    try {
      let clientFolderPath = null;
      let updatedFolders = [...parentFolders];
      // If a folder is pending creation, create it now
      if (pendingClientFolder) {
        // Call your createFolder API here
        const created = await createFolder(pendingClientFolder.path);
        if (created) {
          updatedFolders.push({
            id: created.id,
            name: pendingClientFolder.name,
            path: pendingClientFolder.path,
          });
          clientFolderPath = pendingClientFolder.path;
        }
        setPendingClientFolder(null);
      }
      // Use the selected or matched location if not pending
      const selectedCategory = selectedOption ? selectedOption.value : clientMatches.length === 1 ? clientMatches[0].path : "";
      const clientNameToUse = clientInput.trim();
      const basePath = clientFolderPath || (selectedCategory ? `${selectedCategory}/${clientNameToUse}` : clientNameToUse);
      const fullPath = `${basePath}/${data.clientMatter}`;
      // Now create the matter folder as before
      const isExisting = updatedFolders.some((item) => item.path.toLowerCase() === fullPath.toLowerCase());
      if (isExisting) {
        toast.info("Client and client matter already exist at the selected location");
        setIsLoading(false);
        return;
      }
      try {
        const clientMatterFolder = await createFolder(fullPath);
        if (clientMatterFolder) {
          updatedFolders.push({
            id: clientMatterFolder.id,
            name: data.clientMatter,
            path: fullPath,
          });
        }
      } catch (error) {
        toast.error("Failed to create client matter folder.");
      }
      window.localStorage.setItem("oneDriveFolders", JSON.stringify(updatedFolders));
      setParentFolders(updatedFolders);
      toast.success("Client and client matter created successfully");
    } catch (err) {
      console.error(err);
      toast.error("Something went wrong.");
    } finally {
      setIsLoading(false);
    }
  };

  const syncDriveFolders = async () => {
    setIsLoading(true);
    try {
      const folders = await getOneDriveFolders();
      window.localStorage.setItem("oneDriveFolders", JSON.stringify(folders));
      setParentFolders(folders);

      const optionsData = folders
        .filter((folder) => !folder.path.includes("/"))
        .map((folder) => ({ value: folder.path, label: folder.name }));
      setOptions(optionsData);

      toast.success("Drive synced successfully!");
    } catch (err) {
      console.error("Error syncing folders:", err);
      toast.error("Failed to sync folders.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {isLoading && <Loader />}
      <div className="main-container">
        <Header />
        <div className="background-overlay"></div>
        <ToastContainer position="bottom-center" autoClose={3000} hideProgressBar />

        <div className="logo-style" style={{ paddingTop: "60px" }}>
          <img src={Logo} alt="Company Logo" width={100} height={100} />
        </div>

        {/* Styled Back link with chevron */}
        <div style={{ display: "flex", justifyContent: "center", marginTop: "-6px" }}>
          <button
            type="button"
            onClick={goToHome}
            style={{
              background: "none",
              border: "none",
              color: "#2563eb",
              fontSize: 16,
              display: "flex",
              alignItems: "center",
              cursor: "pointer",
              padding: 0,
              textDecoration: "none",
              outline: "none",
              gap: 2,
            }}
            onMouseOver={(e) => (e.currentTarget.style.textDecoration = "underline")}
            onMouseOut={(e) => (e.currentTarget.style.textDecoration = "none")}
          >
            <ChevronLeft size={20} style={{ marginRight: -2 }} />
            Back
          </button>
        </div>

        <div className="create-client">
          <h3 style={{ fontWeight: 600, textAlign: "center" }}>CREATE A CLIENT MATTER</h3>
          <form onSubmit={handleSubmit(onSubmitHandler)}>
            <div className="create-client-inputs">
              <label style={{ marginTop: "12px", marginBottom: "4px" }}>Client Name:</label>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <Input
                  placeholder="Enter client name here"
                  isInvalid={!!errors.clientName}
                  {...register("clientName", { required: "Client Name is required!" })}
                  value={clientInput}
                  onChange={e => setClientInput(e.target.value)}
                  style={{
                    width: (clientInput && (filteredOptions.length > 0 || filteredOptions.length === 0)) ? 'calc(100% - 40px)' : '100%',
                    transition: 'width 0.2s',
                  }}
                  autoComplete="off"
                />
                {clientInput && filteredOptions.length > 0 && (
                  <CheckmarkCircle24Filled primaryFill="#22c55e" />
                )}
                {clientInput && filteredOptions.length === 0 && (
                  <button
                    type="button"
                    style={{ background: "none", border: "none", padding: 0, cursor: "pointer" }}
                    onClick={handleAddFolder}
                  >
                    <FolderAdd24Filled primaryFill="#2563eb" />
                  </button>
                )}
              </div>
              {errors.clientName && <p className="error-message">{errors.clientName.message}</p>}

              {/* If exactly one match, show its path below the input */}
              {filteredOptions.length === 1 && (
                <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>
                  Client Folder: One Drive/.../{filteredOptions[0].path}
                </div>
              )}

              {/* If multiple matches, show dropdown and selected path */}
              {filteredOptions.length > 1 && (
                <>
                  <label style={{ marginBottom: "4px" }}>Select Location:</label>
                  <Select
                    options={filteredOptions.map(folder => ({ value: folder.path, label: folder.name }))}
                    placeholder="Select an option"
                    value={selectedOption}
                    onChange={opt => {
                      setSelectedOption(opt);
                      setSelectedPath(opt.value);
                    }}
                    isSearchable
                  />
                  {selectedOption && (
                    <div style={{ fontSize: 13, color: "#666", marginBottom: 8 }}>
                      Client Folder: One Drive/.../{selectedOption.value}
                    </div>
                  )}
                </>
              )}

              {/* If no matches, show dropdown for all parent locations (already implemented) */}
              {filteredOptions.length === 0 && options.length > 0 && (
                <>
                  <label style={{ marginBottom: "4px" }}>Select Location:</label>
                  <Select
                    options={options}
                    placeholder="Select an option"
                    value={selectedOption}
                    onChange={opt => {
                      setSelectedOption(opt);
                      setSelectedPath(opt.value);
                    }}
                    isSearchable
                  />
                </>
              )}

              <label style={{ marginTop: "12px", marginBottom: "4px" }}>Client Matter:</label>
              <Input
                placeholder="Enter matter name here"
                isInvalid={!!errors.clientMatter}
                {...register("clientMatter", { required: "Client Matter is required!" })}
              />
              {errors.clientMatter && <p className="error-message">{errors.clientMatter.message}</p>}

              <Button
                appearance="primary"
                className="create-client-btn"
                style={{ padding: "10px", width: "100%", marginTop: "30px" }}
                shape="circular"
                type="submit"
              >
                CREATE CLIENT MATTER
              </Button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
};

export default CreateClientMatter;
