import { accountManager } from '../msal/authConfig';
import { config } from '../config';

export const createFolder = async (folderPath) => {
  return new Promise(async (resolve, reject) => {
    try {
      // Get fresh token
      const token = await accountManager.ssoGetToken(config.SCOPES);

      // Split the path to get the parent folder and new folder name
      let pathParts = folderPath.split("/");
      let folderName = pathParts.pop(); // Last part is the new folder name
      let parentPath = pathParts.join("/"); // Parent path

      // Prepare the API URL
      let apiUrl = `https://graph.microsoft.com/v1.0/me/drive/root:/${parentPath}:/children`;

      // API request to create the folder
      let response = await fetch(apiUrl, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name: folderName,
          folder: {},
          "@microsoft.graph.conflictBehavior": "rename", // Avoid name conflicts
        }),
      });

      // Handle rate limiting
      if (response.status === 429) {
        const retryAfter = response.headers.get("Retry-After") || 5;
        console.warn(`Rate limit hit! Retrying after ${retryAfter} seconds...`);
        await new Promise((resolve) => setTimeout(resolve, retryAfter * 1000));
        return createFolder(folderPath);
      }

      // Handle token expiration
      if (response.status === 401) {
        console.log("Token expired, attempting to refresh...");
        window.localStorage.removeItem('client_matter_token');
        const newToken = await accountManager.ssoGetToken(config.SCOPES);
        
        const retryResponse = await fetch(apiUrl, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${newToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            name: folderName,
            folder: {},
            "@microsoft.graph.conflictBehavior": "rename",
          }),
        });

        if (!retryResponse.ok) {
          const error = await retryResponse.json();
          console.error(`Error creating folder '${folderPath}':`, error);
          reject(error);
          return;
        }

        const result = await retryResponse.json();
        console.log(`Folder '${folderPath}' created successfully.`);
        resolve(result);
        return;
      }

      if (!response.ok) {
        const error = await response.json();
        console.error(`Error creating folder '${folderPath}':`, error);
        reject(error);
        return;
      }

      const result = await response.json();
      console.log(`Folder '${folderPath}' created successfully.`);
      resolve(result);
    } catch (error) {
      console.error(`Unexpected error creating folder '${folderPath}':`, error);
      reject(error);
    }
  });
};
