export function getCurrentEmailAsEML() {
  return new Promise((resolve, reject) => {
    Office.context.mailbox.getCallbackTokenAsync( { isRest: true },async function (result) {
      if (result.status !== Office.AsyncResultStatus.Succeeded) {
        return reject("Failed to get token");
      }

      const token = result.value;
      const messageId = await getItemRestId();
      const restUrl = Office.context.mailbox.restUrl;
      const getMessageUrl = `${restUrl}/v2.0/me/messages/${messageId}/$value`;

      fetch(getMessageUrl, {
        method: "GET",
        headers: { Authorization: `Bearer ${token}` },
      })
        .then((response) => response.blob())
        .then((blob) => resolve(blob))
        .catch((error) => reject(error));
    });
  });
}

export async function getAttachments() {
  return new Promise((resolve, reject) => {
    const item = Office.context.mailbox.item;
    const attachments = item.attachments || [];

    if (attachments.length === 0) {
      console.log("No attachments found.");
      return resolve([]);
    }

    let attachmentPromises = attachments.map((attachment) => {
      return new Promise((resolveAttachment, rejectAttachment) => {
        item.getAttachmentContentAsync(attachment.id, (result) => {
          if (result.status === Office.AsyncResultStatus.Succeeded) {
            const content = result.value.content;
            const blob = b64toBlob(content, attachment.contentType);
            resolveAttachment({ name: attachment.name, blob });
          } else {
            rejectAttachment(`Failed to get attachment: ${attachment.name}`);
          }
        });
      });
    });

    Promise.all(attachmentPromises)
      .then((results) => resolve(results))
      .catch((error) => reject(error));
  });
}
function b64toBlob(b64Data, contentType) {
  const byteCharacters = atob(b64Data);
  const byteNumbers = new Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) {
    byteNumbers[i] = byteCharacters.charCodeAt(i);
  }
  const byteArray = new Uint8Array(byteNumbers);
  return new Blob([byteArray], { type: contentType });
}



function getItemRestId() {
    if (Office.context.mailbox.diagnostics.hostName === 'OutlookIOS') {
        // itemId is already REST-formatted.
        return Office.context.mailbox.item.itemId;
    } else {
        // Convert to an item ID for API v2.0.
        return Office.context.mailbox.convertToRestId(
            Office.context.mailbox.item.itemId,
            Office.MailboxEnums.RestVersion.v2_0
        );
    }
}

function getattachmentRestId(id) {
    if (Office.context.mailbox.diagnostics.hostName === 'OutlookIOS') {
        // itemId is already REST-formatted.
        return Office.context.mailbox.item.itemId;
    } else {
        // Convert to an item ID for API v2.0.
        return Office.context.mailbox.convertToRestId(
            id,
            Office.MailboxEnums.RestVersion.v2_0
        );
    }
};
